import { Component } from '@angular/core';

@Component({
  selector: 'app-nav-menu', // or 'app-nav' if using a separate component
  templateUrl: './nav-menu.component.html', // or './nav.component.html'
  styleUrls: ['./nav-menu.component.css'] // or './nav.component.css'
})
export class NavMenuComponent {
  isExpanded = false;

  toggle() {
    this.isExpanded = !this.isExpanded;
  }

  toggleLanguage() {
    const langToggle = document.getElementById('languageToggle') as HTMLInputElement;
    const isMacedonian = langToggle.checked;
    console.log('Language toggled to:', isMacedonian ? 'Macedonian' : 'English');
    // Add ngx-translate logic here if integrated
  }

  openLoginModal() {
    document.getElementById('loginModal')?.classList.remove('hidden');
  }
}
<header>
  <nav class="navbar navbar-expand-lg navbar-dark bg-custom-dark border-bottom">
    <div class="container" style="max-width: 1200px; margin: 0 auto; padding: 0 1.5rem;">
      <!-- Logo and App Name -->
      <a class="navbar-brand d-flex align-items-center" [routerLink]="['/']">
        <img src="../../assets/smlogo.png" alt="PriceFlow Logo" class="logo">
        <span class="ms-3 text-white fw-bold" style="font-size: 1.6rem; text-shadow: 1px 1px 4px rgba(0, 0, 0, 0.6);">PriceFlow</span>
      </a>
      <button class="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#navbarNav" aria-controls="navbarNav" aria-expanded="false" aria-label="Toggle navigation">
        <span class="navbar-toggler-icon"></span>
      </button>
      <div class="collapse navbar-collapse justify-content-end" id="navbarNav">
        <div class="d-flex align-items-center ms-3">
          <!-- Language Toggle -->
          <div class="language-switch-container">
            <label class="language-switch">
              <input type="checkbox" id="languageToggle" (change)="toggleLanguage()">
              <span class="language-slider"></span>
            </label>
          </div>
          <!-- Login Button -->
          <button (click)="openLoginModal()" class="btn btn-primary ms-3 login">
            LOGIN
          </button>
        </div>
      </div>
    </div>
  </nav>
</header>
